//! Repeatable response sections: several named blocks in one [`crate::AgentResponse`].

use crate::kv::KvItem;
use crate::toon::Value;

/// One named block within a response. A response may hold any number; they render in insertion order.
///
/// A section is a root key of the rendered TOON document: a list or text section under its `name`, a KV section as its
/// item keys. Root keys must be unique, so two sections cannot share a name, and no name or KV key may be one of the
/// keys michi writes itself (`budget`, `sections`, `provenance`, `truncated`, `totalCount`, `help`, `recovery`,
/// `error`, `message`, `causes`, `exit_code`). A response that breaks this renders the `toon_validation_failed` (or
/// `kv_validation_failed`) error naming the key, never invalid TOON.
///
/// The fields are private, so what a section reports about itself has one source each: [`count`](Self::count) is the
/// body's rows or items, [`total`](Self::total) is the one number the caller sets, and
/// [`truncated`](Self::truncated) is derived from those two. No section can print `totalCount: 5` while its JSON says
/// it was not cut.
///
/// # Stability
///
/// The multi-section envelope (this type, [`crate::BudgetSummary`], [`crate::ProvenanceBlock`]) is unstable. It
/// shipped ahead of a second independent consumer (ADR 10), so its shape may change before 1.0, and 1.0 promises only
/// what consumers have used by then.
#[derive(Debug, Clone)]
pub struct Section {
    name: String,
    body: SectionBody,
    total_count: Option<usize>,
}

/// What a [`Section`] holds.
#[derive(Debug, Clone)]
#[non_exhaustive]
pub enum SectionBody {
    /// A uniform list, rendered as a TOON list with the response's per-cell truncation applied.
    Toon {
        /// Ordered, distinct field names.
        fields: Vec<String>,
        /// Rows, parallel to `fields`.
        rows: Vec<Vec<Value>>,
    },
    /// A single receipt or a small set of labelled scalars.
    Kv(Vec<KvItem>),
    /// One string value, rendered as `name: <value>` and escaped like any other TOON string (quoted when it has a
    /// newline, a colon, or looks like a number). Prose cannot start a line of its own, so it cannot forge a `help[]`
    /// line. It is not a way to insert a fragment of TOON.
    Text {
        /// The value.
        text: String,
        /// How many items the prose stands for, since michi cannot count items in prose.
        count: usize,
    },
}

impl Section {
    /// A TOON list section. Its count is `rows.len()`.
    #[must_use]
    pub fn toon(name: impl Into<String>, fields: Vec<String>, rows: Vec<Vec<Value>>) -> Self {
        Self::with(name, SectionBody::Toon { fields, rows })
    }

    /// A key-value section. Its count is `items.len()`.
    #[must_use]
    pub fn kv(name: impl Into<String>, items: Vec<KvItem>) -> Self {
        Self::with(name, SectionBody::Kv(items))
    }

    /// A text section: a single string value, rendered as `name: <escaped body>`. Its count is 1 for non-empty text
    /// and 0 for empty; use [`text_with_count`](Self::text_with_count) when the prose stands for more items.
    #[must_use]
    pub fn text(name: impl Into<String>, body: impl Into<String>) -> Self {
        let text = body.into();
        let count = usize::from(!text.is_empty());
        Self::with(name, SectionBody::Text { text, count })
    }

    /// A text section that stands for `count` items, such as a summary of `count` matches.
    #[must_use]
    pub fn text_with_count(name: impl Into<String>, body: impl Into<String>, count: usize) -> Self {
        Self::with(name, SectionBody::Text { text: body.into(), count })
    }

    fn with(name: impl Into<String>, body: SectionBody) -> Self {
        Self { name: name.into(), body, total_count: None }
    }

    /// Record how many items existed before a cut. `Some(n)` with `n` greater than [`count`](Self::count) renders
    /// `totalCount: n` and makes [`truncated`](Self::truncated) true.
    #[must_use]
    pub fn total_count(mut self, total: Option<usize>) -> Self {
        self.total_count = total;
        self
    }

    /// The section's type name: the identifier at the head of its TOON line, and the key of a text body. A KV body
    /// prints no heading, so there the name only labels it for the caller (and for `sections` in JSON).
    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    /// The section's contents.
    #[must_use]
    pub fn body(&self) -> &SectionBody {
        &self.body
    }

    /// How many items this section carries: `rows.len()` or `items.len()` for `Toon` and `Kv` bodies, the count given
    /// to the constructor for `Text`.
    #[must_use]
    pub fn count(&self) -> usize {
        match &self.body {
            SectionBody::Toon { rows, .. } => rows.len(),
            SectionBody::Kv(items) => items.len(),
            SectionBody::Text { count, .. } => *count,
        }
    }

    /// The pre-cut total set with [`total_count`](Self::total_count), as given.
    #[must_use]
    pub fn total(&self) -> Option<usize> {
        self.total_count
    }

    /// Whether this section was cut: its total exceeds its count. Derived, never set.
    #[must_use]
    pub fn truncated(&self) -> bool {
        self.shown_total().is_some()
    }

    /// The `totalCount` to render: the total only when it exceeds [`count`](Self::count).
    pub(crate) fn shown_total(&self) -> Option<usize> {
        self.total_count.filter(|n| *n > self.count())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn truncated_is_exactly_total_above_count() {
        let one = || Section::toon("t", vec!["a".into()], vec![vec![Value::Int(1)]]);
        assert!(one().total_count(Some(2)).truncated());
        assert!(!one().total_count(Some(1)).truncated());
        assert!(!one().total_count(Some(0)).truncated());
        assert!(!one().truncated());
        assert!(Section::text_with_count("n", "x", 3).total_count(Some(4)).truncated());
        assert!(!Section::text_with_count("n", "x", 3).total_count(Some(3)).truncated());
    }
}
//! The hand-built JSON writers behind every structured companion (`AgentResponse`'s JSON and `structuredContent`,
//! `DomainError`'s `render(OutputFormat::Json)`, the `params` cell of a recovery table). One copy of each writer, so a
//! shape fixed here is fixed everywhere. Hand-built so the default build needs no `serde_json`; the `serde` feature's derives are
//! checked against these writers in tests.

use std::fmt::Write as _;

use crate::kv::KvValue;
use crate::recovery::RecoveryHint;
use crate::toon::Value;

/// Append `s` as a JSON string: quoted, with `"`, `\` and every control character below U+0020 escaped.
pub(crate) fn push_str(out: &mut String, s: &str) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            other if u32::from(other) < 0x20 => {
                let code = u32::from(other);
                out.push_str("\\u00");
                out.push(char::from_digit(code >> 4, 16).unwrap_or('0'));
                out.push(char::from_digit(code & 0xf, 16).unwrap_or('0'));
            }
            other => out.push(other),
        }
    }
    out.push('"');
}

/// Append `true` or `false`.
pub(crate) fn push_bool(out: &mut String, b: bool) {
    out.push_str(if b { "true" } else { "false" });
}

/// Append an unsigned integer.
pub(crate) fn push_uint(out: &mut String, n: impl Into<u64>) {
    let _ = write!(out, "{}", n.into());
}

/// Append a JSON array: `[`, each item written by `item` with a comma between, `]`.
pub(crate) fn push_array<T>(
    out: &mut String,
    items: impl IntoIterator<Item = T>,
    mut item: impl FnMut(&mut String, T),
) {
    out.push('[');
    for (i, x) in items.into_iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        item(out, x);
    }
    out.push(']');
}

/// Append a JSON array of strings.
pub(crate) fn push_str_array<'a>(out: &mut String, items: impl IntoIterator<Item = &'a str>) {
    push_array(out, items, push_str);
}

/// Append a KV value. Non-finite floats are `null`, the token the TOON body uses (§3), so the surfaces agree.
pub(crate) fn push_kv_value(out: &mut String, value: &KvValue) {
    match value {
        KvValue::Text(s) => push_str(out, s),
        KvValue::Int(n) => {
            let _ = write!(out, "{n}");
        }
        KvValue::Float(f, decimals) => {
            if !f.is_finite() {
                out.push_str("null");
            } else if *decimals == KvValue::FULL_PRECISION {
                // TOON's canonical number form is also valid JSON (`1e-300`, `1e+21`), and padding to 255 places
                // would round a smaller value to zero.
                crate::toon::push_f64(out, *f);
            } else {
                let _ = write!(out, "{f:.*}", usize::from(*decimals));
            }
        }
        KvValue::Bool(b) => push_bool(out, *b),
        KvValue::Duration(d) => {
            let mut secs = String::with_capacity(16);
            let _ = write!(secs, "{:.1}s", d.as_secs_f64());
            push_str(out, &secs);
        }
        KvValue::Missing => out.push_str("null"),
    }
}

/// Append a TOON cell value. Non-finite floats are `null`, as in the text render.
pub(crate) fn push_value(out: &mut String, v: &Value) {
    match v {
        Value::Str(s) => push_str(out, s),
        Value::Int(n) => {
            let _ = write!(out, "{n}");
        }
        Value::UInt(n) => push_uint(out, *n),
        Value::Float(f) => crate::toon::push_f64(out, *f),
        Value::Bool(b) => push_bool(out, *b),
        Value::Null => out.push_str("null"),
    }
}

/// Append recovery parameters as a JSON object. A repeated key is written once, at its first position, with its last
/// value -- what [`RecoveryHint::param`] would have produced -- so the object never holds a duplicate key.
pub(crate) fn push_params(out: &mut String, params: &[(String, KvValue)]) {
    out.push('{');
    // Each key's last value, then one pass in order writing a key the first time it is seen: O(P), not O(P²).
    // Internal lookup state only; the output order comes from `params`.
    #[allow(clippy::disallowed_types)]
    let mut last: std::collections::HashMap<&str, &KvValue> = std::collections::HashMap::with_capacity(params.len());
    for (k, v) in params {
        last.insert(k.as_str(), v);
    }
    let mut first = true;
    for (k, _) in params {
        let Some(v) = last.remove(k.as_str()) else { continue };
        if !first {
            out.push(',');
        }
        first = false;
        push_str(out, k);
        out.push(':');
        push_kv_value(out, v);
    }
    out.push('}');
}

/// Append one recovery hint as `{"tool":…,"params":{…}}`, plus `"reason":…` only when it has one.
pub(crate) fn push_recovery(out: &mut String, r: &RecoveryHint) {
    out.push_str("{\"tool\":");
    push_str(out, &r.tool);
    out.push_str(",\"params\":");
    push_params(out, &r.params);
    if let Some(reason) = &r.reason {
        out.push_str(",\"reason\":");
        push_str(out, reason);
    }
    out.push('}');
}

#[cfg(test)]
mod tests {
    use super::*;

    fn str_json(s: &str) -> String {
        let mut out = String::new();
        push_str(&mut out, s);
        out
    }

    #[test]
    fn strings_escape_quotes_backslashes_and_control_characters() {
        assert_eq!(str_json("a\"b\\c\nd\re\tf\u{1}g\u{1f}"), r#""a\"b\\c\nd\re\tf\u0001g\u001f""#);
        assert_eq!(str_json("é\u{2028}"), "\"é\u{2028}\"");
    }

    #[test]
    fn arrays_separate_items_with_one_comma() {
        let mut out = String::new();
        push_str_array(&mut out, ["a", "b", "c"]);
        assert_eq!(out, r#"["a","b","c"]"#);
        let mut empty = String::new();
        push_str_array(&mut empty, []);
        assert_eq!(empty, "[]");
    }

    #[test]
    fn recovery_omits_an_absent_reason() {
        let mut out = String::new();
        push_recovery(&mut out, &RecoveryHint::new("t").param("n", KvValue::Int(1)));
        assert_eq!(out, r#"{"tool":"t","params":{"n":1}}"#);
        out.clear();
        push_recovery(&mut out, &RecoveryHint::new("t").reason("why"));
        assert_eq!(out, r#"{"tool":"t","params":{},"reason":"why"}"#);
    }

    #[cfg(feature = "serde")]
    #[test]
    fn recovery_matches_the_serde_wire_form() {
        let r = RecoveryHint::new("q\"t").param("k", KvValue::Float(f64::NAN, 2)).reason("r\n");
        let mut out = String::new();
        push_recovery(&mut out, &r);
        let hand: serde_json::Value = serde_json::from_str(&out).expect("valid JSON");
        assert_eq!(hand["tool"], "q\"t");
        assert_eq!(hand["reason"], "r\n");
        assert!(hand["params"]["k"].is_null());
    }
}

